DELIMITER $$
--
-- Procedimientos
--
DROP PROCEDURE IF EXISTS `actualizar_disponibilidad_motos`$$
CREATE PROCEDURE `actualizar_disponibilidad_motos` ()   BEGIN
    UPDATE motos 
    SET disponible = 0 
    WHERE id IN (
        SELECT DISTINCT moto_id 
        FROM alquileres 
        WHERE estado IN ('confirmado', 'en curso')
          AND CURDATE() <= fecha_fin
    );

    UPDATE motos 
    SET disponible = 1 
    WHERE id NOT IN (
        SELECT DISTINCT moto_id 
        FROM alquileres 
        WHERE estado IN ('confirmado', 'en curso')
          AND CURDATE() <= fecha_fin
    );
END$$

DROP PROCEDURE IF EXISTS `actualizar_estados_alquileres`$$
CREATE PROCEDURE `actualizar_estados_alquileres` ()   BEGIN
    
    UPDATE alquileres 
    SET estado = 'en curso' 
    WHERE fecha_inicio <= CURDATE() 
    AND fecha_fin >= CURDATE() 
    AND estado = 'completado';

    
    UPDATE alquileres 
    SET estado = 'finalizado' 
    WHERE fecha_fin < CURDATE() 
    AND (estado = 'en curso' OR estado = 'completado');
END$$

DROP PROCEDURE IF EXISTS `actualizar_sistema_completo`$$
CREATE PROCEDURE `actualizar_sistema_completo` ()   BEGIN
    UPDATE alquileres 
    SET estado = 'en_curso' 
    WHERE fecha_inicio <= CURDATE() 
    AND fecha_fin >= CURDATE() 
    AND estado = 'confirmado';

    
    UPDATE alquileres 
    SET estado = 'finalizado' 
    WHERE fecha_fin < CURDATE() 
    AND estado IN ('confirmado', 'en_curso');

    
    UPDATE alquileres 
    SET estado = 'cancelado' 
    WHERE fecha_inicio <= CURDATE() 
    AND estado = 'pendiente';

    
    UPDATE motos SET disponible = 1;
    UPDATE motos SET disponible = 0 
    WHERE id IN (SELECT moto_id FROM alquileres WHERE estado = 'en_curso');
END$$

DROP PROCEDURE IF EXISTS `sp_gestionar_estado_alquiler`$$
CREATE PROCEDURE `sp_gestionar_estado_alquiler` (IN `p_alquiler_id` INT)   BEGIN
    DECLARE v_fecha_inicio DATE;
    DECLARE v_estado_actual VARCHAR(20);

        SELECT fecha_inicio, estado INTO v_fecha_inicio, v_estado_actual 
    FROM alquileres WHERE id = p_alquiler_id;

        IF v_estado_actual = 'completado' AND v_fecha_inicio <= CURDATE() THEN
        UPDATE alquileres SET estado = 'en curso' WHERE id = p_alquiler_id;
    END IF;
END$$

--
-- Funciones
--
DROP FUNCTION IF EXISTS `antiguedad_usuario`$$
CREATE FUNCTION `antiguedad_usuario` (`p_usuario_id` INT) RETURNS INT DETERMINISTIC begin
    declare v_dias int;
    select datediff(curdate(), fecha_registro) into v_dias 
    from usuarios 
    where id = p_usuario_id;
    return v_dias;
end$$

DROP FUNCTION IF EXISTS `calcular_precio_total`$$
CREATE FUNCTION `calcular_precio_total` (`p_moto_id` INT, `p_f_inicio` DATE, `p_f_fin` DATE) RETURNS DECIMAL(10,2) DETERMINISTIC BEGIN
    DECLARE v_precio_dia DECIMAL(10,2);
    DECLARE v_total DECIMAL(10,2);
    DECLARE v_dias INT;


    SELECT precio_dia INTO v_precio_dia FROM motos WHERE id = p_moto_id;
    

    SET v_dias = DATEDIFF(p_f_fin, p_f_inicio) + 1;

    SET v_total = v_precio_dia * v_dias;
    
    RETURN v_total;
END$$

DROP FUNCTION IF EXISTS `total_gastadoo`$$
CREATE FUNCTION `total_gastadoo` (`p_usuario_id` INT) RETURNS DECIMAL(10,2) DETERMINISTIC begin
    declare v_total decimal(10,2);
    select sum(precio_total) into v_total 
    from alquileres 
    where usuario_id = p_usuario_id and estado = 'confirmado';
    if v_total is null then set v_total = 0.00; end if;
    return v_total;
end$$

