DROP TRIGGER IF EXISTS `email_minuscula`;
DELIMITER $$
CREATE TRIGGER `email_minuscula` BEFORE INSERT ON `usuarios` FOR EACH ROW begin
    set new.email = lower(new.email);
end
$$
DELIMITER ;
DROP TRIGGER IF EXISTS `nombre_mayuscula`;
DELIMITER $$
CREATE TRIGGER `nombre_mayuscula` BEFORE INSERT ON `usuarios` FOR EACH ROW begin
    set new.nombre = upper(new.nombre);
end
$$
DELIMITER ;

